      "b": "<p>五行指木、火、土、金、水五种基本物质及其运动变化，古人用它归类万物。<b>木</b>主生长、条达；<b>火</b>主炎热、向上；<b>土</b>主承载、化育；<b>金</b>主收敛、肃杀；<b>水</b>主润下、寒凉。口诀：<b>「木火土金水，生发长收藏」</b>，对应春生、夏长、长夏化、秋收、冬藏。联想记忆：春天草木萌发属木，夏天烈日属火，秋天金属收割属金，冬天结冰属水，四季之末的土负责转化。</p><p>常见误区：把五行当成五种具体物质——其实它是五种<b>属性类别</b>，比如「金」也代表肺、白色、西方。例：一个人性格急躁属火，性格温和属水，这是属性归类而非说人由火与水组成。</p>"
