      "h": "五行相克",
      "b": "<p>相克是五行之间<b>互相制约、克制</b>的关系：木克土、土克水、水克火、火克金、金克木。联想：树木破土而出（木克土）；堤坝拦水（土克水）；水能灭火（水克火）；火能熔金（火克金）；刀斧砍木（金克木）。口诀：<b>「木土水火金，隔一相克」</b>——在圆中每隔一位即相克。相克并非坏事，它是维持平衡的力量，如同刹车让车不失控。</p><p>常见误区：认为「克=凶」。其实适度相克是健康的，比如水克火可防止火过旺。例：火旺之人需水来调候，正是用克来平衡，并非水来伤害火。</p>"
