      "b": "<p>日柱是四柱中最需要计算的一柱，因为日的干支每60天循环，无法直接靠年份推。常用方法：</p><ul><li>查万年历（最常用、最准确）。</li><li>用公式推算（较复杂，新手不推荐）。</li></ul><p>口诀：<b>「日柱查日历，六十转一圈」</b>。新手建议直接用万年历或排盘软件确定日干支。</p><p>常见误区：以为日柱和年月一样能口算——日干支跨度不规则，手动极易错。例：查万年历可确认当日日柱，这就是当日出生人的日柱。</p>"
