      "h": "克我者：正官与七杀",
      "b": "<p>克我（日干）的五行是「官杀」。阴阳同性为<b>七杀</b>（偏官），异性为<b>正官</b>。<br>例：日干甲木，金克木，庚金(阳)同性→七杀；辛金(阴)异性→正官。<br>含义：官杀代表<b>事业、约束、丈夫（女命）、权力、压力</b>。正官正统守法，七杀果断狠厉。口诀：<b>「克我官杀，同性七杀异性官」</b>。</p><p>常见误区：七杀=凶——七杀有制反成大权。例：官星为喜者责任感强、易掌权；七杀为用配印，多为将才。</p>"
