      "b": "<p><b>日主</b>就是日柱的天干，代表命主本人，是整张命盘的中心，所有十神都围绕它。八字分析第一步永远是「看清日主是谁、什么五行」。口诀：<b>「日干即我身，万事绕它转」</b>。联想：日主像舞台中央的主角，其余七字是配角。</p><p>常见误区：把年干当自己——年干代表祖上，不是本人。例：日柱甲子，日主就是「甲」木，全盘的生克都以甲为中心展开。</p>"
