      "b": "<p><b>大运</b>是人生每十年一换的「运势阶段」，像十年一期的大气候。八字是静态命局，大运是动态时间轴，二者结合才知何时顺逆。口诀：<b>「命为车，运为路；大运十年一转折」</b>。联想：命局是出厂配置，大运是不同路况。</p><p>常见误区：以为八字定终身——其实大运流年会让同八字的人际遇起伏不同。例：用神火的人，走火运十年就顺，走水运则压抑。</p>"
