      "b": "<p>用十神「代入」家庭成员，是八字看六亲的基础：</p><table><tr><th>亲属</th><th>男命对应</th><th>女命对应</th></tr><tr><td>父亲</td><td>偏财</td><td>正财</td></tr><tr><td>母亲</td><td>正印</td><td>正印</td></tr><tr><td>妻子</td><td>正财</td><td>（夫）正官</td></tr><tr><td>丈夫</td><td>（妻）正财</td><td>正官</td></tr><tr><td>子女</td><td>官杀（男）</td><td>食伤（女）</td></tr><tr><td>兄弟</td><td>比劫</td><td>比劫</td></tr></table><p>口诀：<b>「男财为妻父偏，女官为夫；印为母，比劫为兄弟」</b>。常见误区：男女六亲星不同，别混用。</p>"
