     "b": "<p>我们用一个全新八字做全流程演练：<b>壬申 辛亥 甲子 乙丑</b>（男）。</p><p>①排盘：年壬申、月辛亥、日甲子、时乙丑。</p><p>②日主甲木，十神：年干壬偏印、申中庚杀；月干辛正官、亥中壬甲；日支子正印；时干乙劫财、丑中己正财辛官癸印。</p><p>③藏干刑冲：申子半合水，水极旺；无冲。</p><p>④旺衰：甲生亥月（水令，印旺）得令，地支子亥水、申丑湿土，水多木漂浮——身弱（水多漂木，印重反溺）。</p><p>⑤格局：月令亥中壬水偏印→偏印格，官印相生。</p><p>⑥用神：身弱水泛，喜土制水、火调候、木帮身→用神土火木；忌金水。</p><p>⑦大运：辛亥顺排（阳男）壬子癸丑…水运早岁压力大，中年火土运起。</p><p>⑧六亲事业：印旺母荫、官印相生宜文职，财弱需运补。结论：聪慧得长辈助，早年水运困，中年火土运发。</p>"
