    "caseStudy": {
     "title": "实例：问考试能否通过",
     "b": "<p>某人问「下月考试能否通过」，摇得地水师卦（坎下坤上），假设装卦后六亲（坎宫我=水）：</p><table><tr><th>爻</th><th>地支</th><th>六亲</th><th>角色</th></tr><tr><td>初</td><td>子</td><td>兄弟</td><td>—</td></tr><tr><td>二</td><td>寅</td><td>子孙</td><td>原神（生父母）</td></tr><tr><td>三</td><td>辰</td><td>官鬼</td><td>忌神（克父母）</td></tr><tr><td>四</td><td>丑</td><td>父母</td><td>用神（考试）</td></tr><tr><td>五</td><td>亥</td><td>兄弟</td><td>—</td></tr><tr><td>上</td><td>酉</td><td>妻财</td><td>仇神（生官鬼）</td></tr></table><p>步骤：①问考试→用神取父母爻（四爻丑土父母）。②原神=生父母者，火生土，卦中无火爻，原神虚空（靠月日补）。③忌神=克父母者，木克土，卦中寅木子孙？注意子孙不生父母，官鬼辰土？这里需理清：克土的是木，卦中木爻为寅（子孙）与卯（无）。所以真正忌神应是木爻。但官鬼辰土是同是土，非忌。说明取忌神要回到五行，不能只看六亲名。</p><p>纠正：忌神是克用神五行的爻，用神丑土，克土者木，故寅木子孙在此充当忌神角色（虽名子孙）。这提示：忌神看五行，不局限于官鬼名。此例告诉我们用神选定后，生克按五行走。</p>"
    },
