    "caseStudy": {
     "title": "实例：问投资能否赚钱",
     "b": "<p>某人问「投这笔钱三个月后能否盈利」，摇得火风鼎卦，用神妻财（木）在二爻，原神子孙（水）在四爻发动，忌神兄弟（土？）未动。</p><p>第一步取用：求财→妻财爻，二爻妻财木为用神。第二步看旺衰：假设占于亥月（水）卯日（木），月日水生木，用神大旺。第三步看原神：四爻子孙水发动生妻财木，财源滚滚且发动主成。第四步看忌神：兄弟爻静而不发，无破财之扰。</p><p>细节：妻财临青龙（假设排到）→ 正财喜事；子孙发动临朱雀 → 靠消息口才之财。</p><p>结论：用神旺+原神动生+忌神静 = 投资可盈利。但提示：若占于申酉月（金）克木，则财衰，结论反转，可见旺衰是前提。</p><p>此例串起用神、原神、忌神、旺衰、六神，是分类占断的标准流程。</p>"
    },
