     "title": "实战全流程：问本月能否收到欠款",
     "b": "<p>问题：甲借出一笔钱，问「本月能否收回欠款」。占于农历寅月午日。</p><p>第1步摇卦：得山天大畜，本卦（艮下乾上），假设二爻妻财（寅木）发动，上爻兄弟（戌土？）静。</p><p>第2步装地支：艮宫我=土。下卦艮初辰、二午、三申；上卦乾四戌、五子、上寅。二爻午火实为？注意此处为演示，假定二爻为妻财寅木发动（按艮宫：初辰土父母、二午火官鬼、三申金兄弟；上乾四戌土父母、五子水妻财、上寅木兄弟）。为贴合用神，我们取五爻子水妻财为用神（问财）。</p><p>第3步定六亲（我=土）：子水为我克→妻财（用神）在五爻；寅木克土→官鬼在上爻；午火生土→父母二爻；等等。</p><p>第4步取用：妻财子水在五爻为用神。</p><p>第5步察旺衰：寅月（木）午日（火），水（子）被月日泄耗，用神不旺但也不受克（平）。</p><p>第6步生克动变：五爻妻财静，原神（金，生水）有无？三爻申金兄弟（金）静，金生水为原神但静力弱；忌神（土，克水）为辰戌父母动否？皆静。动爻在二爻官鬼午火（火），火耗水（用神），稍不利。</p><p>结论：用神平、原神静、仅官鬼动耗之，收款费力但非全无，需主动催（因用神不空、忌神不兴）。若占于亥子月日水旺，则明显可收回。全流程演示完毕。</p>"
