    "title": "第1章 梅花易数概述与先天八卦数",
    "sections": [
     {
      "h": "什么是梅花易数",
      "b": "梅花易数相传由北宋邵雍（邵康节）创立，是周易占卜中最灵活的一支。它不靠铜钱摇卦，而是\"见机而作\"——听到一个数字、看到一时辰、遇到一件突发小事，都能立刻起卦。其名\"梅花\"，据说因邵雍观梅落枝而占验得名。<br><p>与六爻、奇门相比，梅花易数最突出的特点是\"轻\"：起卦快、用卦少（本卦、互卦、变卦三卦即可）、重体用生克与外应直觉。它不追求繁琐装卦，而讲究\"心易\"——以心观象。本章先打地基：背诵先天八卦数，这是后面所有起卦的钥匙。</p>"
     },
     {
      "h": "认识八卦：三爻成卦",
      "b": "八卦是八个基本符号，每个由三爻组成，爻分阴（断开）与阳（连续）。古人用三爻模拟\"天、人、地\"三才。八种组合如下，请对照记忆：<br><table><tr><th>卦名</th><th>符号</th><th>自然象</th><th>家庭角色</th></tr><tr><td>乾</td><td>☰</td><td>天</td><td>父</td></tr><tr><td>兑</td><td>☱</td><td>泽</td><td>少女</td></tr><tr><td>离</td><td>☲</td><td>火</td><td>中女</td></tr><tr><td>震</td><td>☳</td><td>雷</td><td>长男</td></tr><tr><td>巽</td><td>☴</td><td>风</td><td>长女</td></tr><tr><td>坎</td><td>☵</td><td>水</td><td>中男</td></tr><tr><td>艮</td><td>☶</td><td>山</td><td>少男</td></tr><tr><td>坤</td><td>☷</td><td>地</td><td>母</td></tr></table><p>记不住符号没关系，先记住\"卦名—自然象—家庭角色\"这条线，后面类象全从这儿长出来。</p>"
     },
     {
      "h": "先天八卦数：背诵口诀",
      "b": "起卦时要用\"数\"对应\"卦\"，这套数叫先天八卦数（也叫伏羲数）。必须背熟：<br><table><tr><th>数</th><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td><td>7</td><td>8</td></tr><tr><th>卦</th><td>乾</td><td>兑</td><td>离</td><td>震</td><td>巽</td><td>坎</td><td>艮</td><td>坤</td></tr></table><br><p>口诀：\"乾一兑二离三震四，巽五坎六艮七坤八。\"建议边读边用手指点算。常见误区：有人把先天数当成\"卦的排列顺序\"去记先后天方位，结果起卦取余时张冠李戴。记住：起卦只用先天数，与后天方位无关，后面第2章会反复用到。</p>"
     },
     {
      "h": "八卦的五行归属",
      "b": "断吉凶靠\"五行生克\"，所以每个卦都要归到金木水火土。口诀：\"乾兑金，离火，震巽木，坎水，艮坤土。\"写成表更好记：<br><table><tr><th>五行</th><th>包含的卦</th></tr><tr><td>金</td><td>乾（☰）、兑（☱）</td></tr><tr><td>木</td><td>震（☳）、巽（☴）</td></tr><tr><td>水</td><td>坎（☵）</td></tr><tr><td>火</td><td>离（☲）</td></tr><tr><td>土</td><td>艮（☶）、坤（☷）</td></tr></table><br><p>误区提醒：离卦虽然画着中空，但它五行属火；坎卦属水，别因为\"坎=坎坷\"就误以为是土。生克判断一律以五行属性为准，不以字形为准。</p>"
     },
     {
      "h": "为什么先学数",
      "b": "你可能会问：直接学怎么占不行吗？不行。梅花易数的全部起卦方法——时间起卦、数字起卦、声音起卦、字数起卦——最终都落脚到一句话：\"把某个数，按先天八卦数，换算成一个卦。\"数不会换算，后面全断。<br><p>所以第1章只做三件事：认识八卦、背熟先天数、记住五行归属。做到看到\"3\"立刻想到离卦、想到火，看到\"6\"立刻想到坎卦、想到水，本章就算过关。小检验：乾数几？兑数几？坎属什么五行？能秒答，就可以进入第2章学起卦了。</p>"
     }
    ],
    "caseStudy": {
     "title": "小试身手：用先天数认卦",
     "b": "我们先用最简单的方式熟悉\"数→卦\"的换算，暂不涉动爻。<br><p><b>例：</b>有人报数\"7和2\"，要起一卦。</p><ol><li>第一步：上卦取第一个数 7。查先天数表，7 对应艮卦（☶）。所以上卦=艮。</li><li>第二步：下卦取第二个数 2。2 对应兑卦（☱）。所以下卦=兑。</li><li>第三步：把上下卦叠起，上艮下兑，读作\"山泽损\"卦（艮为山在上，兑为泽在下）。</li></ol><p><b>练习延伸：</b>若报数\"3和6\"，上卦离（火）、下卦坎（水），成\"火水未济\"。你看，只要数熟，换卦就是查表。真正起卦时还会多一个动爻，第2章再讲。</p>"
    },
