      "b": "应期，就是\"所断之事会在什么时候发生/应验\"。梅花断准吉凶后，客户常问\"多久？\"。应期无绝对公式，但有套路。总原则：<b>以卦数、五行、动静三者综合推断，取最贴合问事的一个。</b><br><p>例如占远行几日归、占病几日愈、占求财几月得。应期可论\"日、月、年、时\"，单位由问事性质定：小事用日时，大事用月年。</p>"
