      "h": "什么是心易",
      "b": "\"心易\"是梅花的最高境界，语出邵雍\"心为太极，万物在我\"。意思是：不必拘泥于固定起卦法，心念一动、触机即占，天地万物皆可成卦成象。<br><p>心易不是\"乱猜\"，而是把前面九章（数、卦、体用、生克、类象、应期、外应）内化为直觉后，能随物赋象、灵活取舍。新手先守规矩，熟后方谈\"从心所欲不逾矩\"。本章既总结，也指路。</p>"
