      "h": "什么是奇门遁甲",
      "b": "<p>奇门遁甲是中国传统术数中著名的「帝王之学」，古人用它来排兵布阵、择时决策。</p><p><b>核心思想</b>：把时间（天）和空间（地）叠成一个「盘」，在盘上标注九星、八门、八神、三奇六仪，从而观察事物的发展趋势。</p><ul><li>奇：指乙、丙、丁三奇</li><li>门：指休、生、伤、杜、景、死、惊、开八门</li><li>遁甲：指把「甲」这个天干隐藏起来</li></ul><p>初学者先把奇门理解成一张会随时间转动的「时空棋盘」即可。</p>"
