      "h": "阴阳遁的概念",
      "b": "<p>奇门分<b>阳遁</b>与<b>阴遁</b>：</p><ul><li><b>阳遁</b>：从冬至到夏至，阳气上升，符号顺排（宫数从小到大）。</li><li><b>阴遁</b>：从夏至到冬至，阴气上升，符号逆排（宫数从大到小）。</li></ul><p>一句话：夏半年用阳遁，冬半年用阴遁，由节气决定。</p><p><b>为什么分阴阳</b>：模拟天地阴阳消长，使盘的能量方向符合季节。</p>"
