      "b": "<p>转盘奇门排盘八步：</p><ol><li>定局数（阴阳遁+几局）</li><li>排地盘三奇六仪（戊己庚辛壬癸丁丙乙）</li><li>找旬首→定符首→定值符值使</li><li>排天盘（值符随时干转，带天干）</li><li>排人盘八门（值使随时支转）</li><li>排神盘八神（值符领头顺转）</li><li>布八神、标空亡</li><li>检查用神宫</li></ol><p>现代可用排盘软件验证，但懂原理才看得懂盘。</p>"
