      "h": "十干克应概念",
      "b": "<p>「十干克应」指天盘干与地盘干相叠加时的组合含义，是断细节的关键。</p><p>常见格局例：</p><ul><li><b>戊+戊</b>：伏吟，阻滞，宜静</li><li><b>庚+庚</b>：战格，争斗</li><li><b>乙+辛</b>：青龙逃走，变动不利</li><li><b>丙+庚</b>：荧入太白，贼退</li><li><b>丁+壬</b>：奇仪相合，和顺</li></ul><p>共约 80 余种组合，初学先记十来个常用格。</p>"
