      "b": "<p>「用神」是盘上代表「所问之事/人」的符号，断局先选定用神。</p><p>原则：</p><ul><li>问事主体→看日干（我）与时干（事）。</li><li>特定人事物→用专门用神（如父母看乾坤）。</li></ul><p>选错用神，全盘皆误，所以这是断局第一步。</p><p><b>记忆</b>：「日干为体，时干为用；专事专用，莫错宫位。」</p>"
