      "h": "8.4 Step4 收尾给最小行动",
      "b": "<p>解读结束必须给一句<b>『下周可执行的最小行动』</b>，让牌落回现实。例如抽到宝剑八（束缚），行动就是『明天写下三个你害怕说出口的实话』。没有行动建议的解读，像只诊断不开药。下方『解牌SOP引导器』把四步做成可勾选流程，并可直接存入练习日志。</p>"
