      "b": "<p>感情问题看<b>圣杯（水）</b>系列与宫廷牌（人物）。出现圣杯二/十=关系平等温暖；圣杯三逆=第三者或聚会不欢；宝剑三=心碎；权杖二=是否表白的选择。读感情少下『分/合』定论，多给『关系当下能量』与『可做的沟通』。例如抽到圣杯六，提示『回到轻松熟悉的相处模式』而非『必定复合』。</p>"
