      "b": "<p>天府星系有 <b>八颗</b> 主星：天府、太阴、贪狼、巨门、天相、天梁、七杀、破军。它们与紫微星系六星合为十四主星。</p><p>这八颗性格差异很大，从「稳重的库星」到「破局的先锋」都有：</p><table><tr><th>星</th><th>一句话性格</th></tr><tr><td>天府</td><td>稳重、会理财的库星</td></tr><tr><td>太阴</td><td>温柔、内敛的财星</td></tr><tr><td>贪狼</td><td>多才、桃花、欲望</td></tr><tr><td>巨门</td><td>口才、是非、暗星</td></tr><tr><td>天相</td><td>端庄、掌印的辅星</td></tr><tr><td>天梁</td><td>荫星、老大哥、解厄</td></tr><tr><td>七杀</td><td>孤勇、果决、开拓</td></tr><tr><td>破军</td><td>破旧立新、变动</td></tr></table>"
