      "b": "<p>十四主星像「主角」，但一盘里还有上百颗「配角」。它们不改变主星的根本性格，却像调味料：<b>吉星加料变香，煞星加料变苦</b>。</p><p>配角分几大类：</p><table><tr><th>类别</th><th>代表星</th><th>作用</th></tr><tr><td>六吉星</td><td>左辅右弼文昌文曲天魁天钺</td><td>增吉、助力</td></tr><tr><td>四煞星</td><td>羊陀火铃（擎羊陀罗火星铃星）</td><td>增阻、激发</td></tr><tr><td>其他</td><td>禄存天马空劫等</td><td>特殊性质</td></tr></table><p><b>心法：</b>主星定「是什么」，辅煞星定「好不好、顺不顺」。</p>"
