     "title": "实例：农历八月、卯时生，求命宫",
     "b": "<p>某人农历 <b>八月</b> 生，<b>卯时</b>（5–7点）生。我们按口诀推命宫：</p><ol><li><b>顺数到生月：</b>寅(正月)→卯(2)→辰(3)→巳(4)→午(5)→未(6)→申(7)→酉(8)。停在酉。</li><li><b>逆数到生时：</b>从酉起子时，逆数：酉=子、申=丑、未=寅、午=卯。卯时落在<b>午</b>。</li><li><b>命宫=午。</b></li></ol><p>再顺手定身宫（顺数到卯时）：酉起子顺数，酉=子、戌=丑、亥=寅、子=卯→身宫在子。</p><p><b>结论：</b>命宫午、身宫子。命宫定好后，十二宫顺序即可顺时针排出。你也可立即用排盘软件验证。</p>"
