      "h": "贼克法（元首与重审）",
      "b": "<p>四课中找相克关系：</p><ol><li>先看有无<b>下克上（贼）</b>，有则取被克的「上神」为初传。</li><li>若无贼，看<b>上克下（克）</b>，取克者的「上神」为初传。</li></ol><p>若只有一处克，直接取之：</p><ul><li>唯一上克下 → <b>元首课</b>（君统臣，顺利）。</li><li>唯一下克上 → <b>重审课</b>（以下犯上，多反复）。</li></ul><p><b>例子：</b>四课见「寅·酉」（寅木被酉金克，下克上）→ 初传取酉。中末传取干上、支上。</p>"
