      "b": "<p>四课无克也无遥克时，用<b>昴星法</b>，取地盘「酉」（昴星）相关之神。</p><ul><li><b>阳日（刚日）</b>：取地盘酉上的天盘神为初传。</li><li><b>阴日（柔日）</b>：取天盘酉所落地盘之下的神（酉之阴神）为初传。</li></ul><p>中末传：阳日取干上、支上；阴日取支上、干上。</p><p><b>例子：</b>甲（阳）日无克，地盘酉上天的盘是某神X → 初传X，中传干上，末传支上。</p><p><b>口诀：</b>「无克无遥取昴星，阳从地酉阴从天。」</p>"
