      "b": "<p>由取传方式自然形成的课体（也叫「门」），各有性格：</p><table><tr><th>课体</th><th>成因</th><th>性情</th></tr><tr><td>元首</td><td>唯一上克下</td><td>顺、君统臣</td></tr><tr><td>重审</td><td>唯一下克上</td><td>慎、以下犯上</td></tr><tr><td>知一</td><td>比用</td><td>就近、专一</td></tr><tr><td>涉害</td><td>多比取深</td><td>艰难、历险</td></tr><tr><td>蒿矢/弹射</td><td>遥克</td><td>力弱、虚惊</td></tr></table><p>这些是第一、二章取传法的「名字」，记住名字即知取传逻辑。</p>"
