      "h": "大安 · 木 · 东方",
      "b": "<p><b>大安 · 木 · 东方</b></p><p>诗诀：「大安事事昌，求谋在东方，失物去不远，宅舍保平安。行人身未动，病者主无妨。」</p><p><b>含义</b>：安稳、吉祥、静守。谋事可成但宜缓；失物在近处（家中）；行人尚未动身；疾病无大碍；婚姻可成；官事平和；求财平稳。</p><p><b>读神三钥匙</b>：五行木主生发、方位东、诗诀主静。遇事落大安，先别急着动，稳住就有好结果。常见误区：以为「宜缓」=「不成」，其实是大概率成，只是别冒进。</p>"
