        "b": "<p>小吴家一进门正对厕所门，且主卧床头靠窗。按本章：开门见厕（纳秽）、床头无靠（无靠山）。改造：进门处加一道到顶屏风做玄关，厕所门常关并挂门帘；床头移到有实墙的西侧，窗边改放矮柜。改完他说进门不再直视厕所、睡觉也踏实。两处都是「门主」范畴的最小改动，见效明显。</p>"
