          "h": "什么是手相",
          "b": "<p>很多人以为手相就是看手纹，其实它管的事情比你想的多。简单来说，手相是古人通过观察手掌的<b>纹路、掌型、手指、指甲和掌丘</b>这些部位，来推断一个人性格、健康、感情、事业走向的一门传统相术。</p><p>打个比方，手掌就像一张写满字的纸，纹路是句子，掌丘是标点，手指是笔画。我们读这张纸，不是算命，而是看一个人天生的性格底色和后天可能的变化趋势。</p><p>记住一句话：<b>手相看的是倾向，不是定数</b>。它告诉你可能往哪个方向走，而不是注定发生什么。这是新手最先要摆正的心态。</p>"
