          "b": "<p><b>月丘</b>：手掌靠小指下方那块，代表想象力、直觉与远方。饱满者爱幻想、有灵感，适合创意类。</p><p><b>第一火星丘</b>：金星丘和木星丘之间的鼓起，代表勇气与行动力。<b>第二火星丘</b>：月丘下方，代表耐力和抗压。</p><p>两个火星丘一个管冲劲，一个管持久，是看你敢不敢干、能不能扛的关键。</p>"
