          "h": "掌丘怎么综合看",
          "b": "<p>看掌丘不是单看一个，而是<b>看整体平衡</b>。比如金星丘饱满但第二火星丘平，代表有活力但抗压弱，容易三分钟热度。</p><p>木星丘旺＋太阳丘旺：领导欲和才华都强，易出头。月丘旺＋水星丘平：有想象力但表达跟不上，想法难落地。</p><p>口诀：<b>丘丘有主次，旺弱配着读，单丘不结论，平衡才是谱</b>。</p>"
