          "b": "<p>传统面相有「男相法」与「女相法」的区分，核心不是双重标准，而是<b>关注重心不同</b>。古人社会角色有别，所以观察侧重点不同，今天我们要理解其底层逻辑而非照搬。</p><p>大原则：<b>男重骨与势，女重容与神</b>。男相多看颧鼻权财格局，女相多看神态、气色与整体柔和度。但现代人职业多元，这条要灵活用。</p><p>记住：差异是倾向，不是铁律，男女都可综合看，别拿旧框硬套新的人。</p>"
