          "h": "综合断法三步走",
          "b": "<p>学会了各部位，关键在<b>综合</b>。推荐三步走：第一步<b>定格局</b>，看三庭五眼整体协调否；第二步<b>抓主轴</b>，看鼻（财）、额（业）、下巴（晚）三段主线；第三步<b>看神色</b>，用气色与神做动态校验。</p><p>口诀：「先观全局，再抓主线，后以神色定动静」。顺序错了容易一叶障目。</p><p>类比：综合断法像<b>看病拿整体方案</b>，不能头痛医头，要望闻问切一起上。</p>"
