          "h": "一、测字到底是什么",
          "b": "<p>测字，也叫拆字、破字，是一种把汉字拆开或重新组合，再借字形、字音、字义来推测事情吉凶的占卜方法。</p><p>打个比方：你写一个『忍』字来问一件事能不能成，测字先生会把这个字拆成『刃』和『心』，意思是心头一把刀还要忍住，于是判断你目前要忍耐。</p><p>注意，测字不是猜谜语游戏，它背后有一套把字形和环境、时间结合起来的思路。</p>"
