          "h": "五、本章常见误区",
          "b": "<p>误区一：以为测字就是拆偏旁那么简单。其实字形只是入口，还要结合外应和时间。</p><p>误区二：以为字越复杂越准。简单字一样能断，关键是拆解是否合情理。</p>"
